/// The most cells one viewport describes: a phone screen zoomed all the way out shows a few
/// thousand, so this only stops a hostile request.
const MAX_VIEW_CELLS: u64 = 40_000;

/// The default font's digit width in sheet units, what General numbers are narrowed by when the
/// app gives none.
const DIGIT_WIDTH: f32 = 7.0;

/// What went wrong, as a message the user can act on.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    /// A command failed or was refused: unknown id, bad parameters, nothing to act on…
    #[error("{0}")]
    Command(String),
    /// A file could not be opened.
    #[error("{0}")]
    Open(String),
    /// The workbook is protected with a password and none was given.
    #[error("This workbook is protected with a password.")]
    NeedsPassword,
    /// The password given was wrong.
    #[error("The password isn't correct.")]
    WrongPassword,
    /// The workbook could not be written.
    #[error("{0}")]
    Save(String),
}

impl From<EngineError> for MobileError {
    fn from(e: EngineError) -> Self {
        MobileError::Command(e.to_string())
    }
}

