/// The engine session for one app process.
#[derive(uniffi::Object)]
pub struct MobileSession {
    session: Mutex<Session>,
}

impl Default for MobileSession {
    fn default() -> Self {
        let mut s = Session::new();
        s.new_workbook();
        Self { session: Mutex::new(s) }
    }
}

impl MobileSession {
    /// The session, even when a call panicked while holding it: the engine keeps itself
    /// consistent between commands, and losing the user's workbook would be worse.
    fn lock(&self) -> MutexGuard<'_, Session> {
        self.session.lock().unwrap_or_else(PoisonError::into_inner)
    }

    fn run(s: &mut Session, id: &str, params: Json) -> Result<Json, MobileError> {
        let r = s.execute(id, params);
        // dialogs and messages are for the desktop; the app asks for what it needs itself
        s.take_ui_requests();
        Ok(r?)
    }

    /// The workbook, its active sheet's index and the document's revision, to read without
    /// holding the session.
    /// Chart `id`'s type, colours and title over sample data, with `command` run on it, drawn
    /// `width` × `height`: the Layout and Style galleries' previews.
    fn chart_sample(&self, id: u32, command: &str, params: Json, width: f32, height: f32) -> Vec<ChartPrim> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(own) = wb.sheet(si).and_then(|sh| sh.charts.iter().find(|c| c.id == id)) else { return vec![] };
        let mut s = Session::new();
        s.new_workbook();
        // made in the chart's family (whose layouts these are); a pie's show the shares of four quarters
        let three = || json!([["", "Series1", "Series2", "Series3"], ["Category 1", 4.2, 2.5, 1.9], ["Category 2", 2.6, 4.3, 2.1]]);
        use gridcraft_engine::model::ChartKind as K;
        let (values, range, kind) = match own.kind {
            K::Pie | K::PieOfPie | K::BarOfPie | K::Doughnut => {
                (json!([["", "Sales"], ["Q1", 7.8], ["Q2", 3.5], ["Q3", 1.6], ["Q4", 1.1]]), "A1:B5", "pie")
            }
            K::Line | K::LineMarkers | K::LineStacked | K::LineStackedMarkers | K::LineStacked100 | K::LineStacked100Markers => {
                (three(), "A1:D3", "line")
            }
            // a stock's highs, lows and closes
            K::Stock => (
                json!([["", "High", "Low", "Close"], ["Day 1", 44, 25, 38], ["Day 2", 50, 31, 42], ["Day 3", 41, 28, 33], ["Day 4", 47, 30, 45]]),
                "A1:D5",
                "stock",
            ),
            // a treemap's or sunburst's shares
            K::Treemap | K::Sunburst => (json!([["", "Series1"], ["A", 42], ["B", 28], ["C", 18], ["D", 12]]), "A1:B5", "treemap"),
            // a funnel's narrowing stages
            K::Funnel => (json!([["", "Series1"], ["Stage 1", 100], ["Stage 2", 75], ["Stage 3", 50], ["Stage 4", 25]]), "A1:B5", "funnel"),
            // a box and whisker chart's scores in two groups
            K::BoxWhisker => (
                json!([
                    ["", "Series1", "Series2"],
                    ["A", 42, 60],
                    ["B", 55, 52],
                    ["A", 61, 48],
                    ["B", 38, 71],
                    ["A", 70, 66],
                    ["B", 49, 59],
                    ["A", 53, 63],
                    ["B", 66, 44]
                ]),
                "A1:C9",
                "boxWhisker",
            ),
            // a waterfall's start, ups and downs
            K::Waterfall => (json!([["", "Series1"], ["Start", 100], ["Q1", 20], ["Q2", -15], ["Q3", 30], ["Q4", -10]]), "A1:B6", "waterfall"),
            // a histogram's twenty scores in three bins
            K::Histogram => (
                json!([
                    ["Series1"],
                    [12],
                    [15],
                    [22],
                    [25],
                    [27],
                    [31],
                    [33],
                    [34],
                    [38],
                    [41],
                    [42],
                    [44],
                    [47],
                    [51],
                    [55],
                    [58],
                    [63],
                    [67],
                    [72],
                    [85]
                ]),
                "A1:A21",
                "histogram",
            ),
            // a radar's round five categories
            K::Radar | K::RadarMarkers | K::RadarFilled => (
                json!([
                    ["", "Series1", "Series2"],
                    ["Category 1", 4.3, 2.4],
                    ["Category 2", 2.5, 4.4],
                    ["Category 3", 3.5, 1.8],
                    ["Category 4", 4.5, 2.8],
                    ["Category 5", 2.9, 3.6]
                ]),
                "A1:C6",
                "radar",
            ),
            _ => (three(), "A1:D3", "column"),
        };
        // the title the chart shows: its own, or the one series' name it takes on its own
        let title = match own.title.as_deref().map(str::trim) {
            Some(t) if !t.is_empty() => t.to_string(),
            None if own.series.len() == 1 => gridcraft_chart::resolve(&wb, si, own).series.first().map(|s| s.name.clone()).unwrap_or_default(),
            _ => String::new(),
        };
        let title = if title.is_empty() { "Chart Title".to_string() } else { title };
        let made = s.run("range.setValues", json!({ "range": "A1", "values": values })).is_ok()
            && s.run("insert.chart", json!({ "range": range, "type": kind, "title": title })).is_ok();
        // the sample takes the chart's own type, colours and style before the layout or style goes on
        let Some(d) = s.active_mut().filter(|_| made) else { return vec![] };
        let psi = d.wb.active_sheet;
        let Some(sample) = Arc::make_mut(&mut d.wb).sheet_mut(psi).and_then(|sh| sh.charts.first_mut()) else { return vec![] };
        sample.kind = own.kind;
        sample.depth = own.depth;
        sample.elements.palette = own.elements.palette;
        sample.elements.style = own.elements.style;
        if s.run(command, params).is_err() {
            return vec![];
        }
        let Some(d) = s.active() else { return vec![] };
        let Some(chart) = d.wb.sheet(psi).and_then(|sh| sh.charts.first()).cloned() else { return vec![] };
        let size = |v: f32| if v.is_finite() { v.clamp(1.0, 4096.0) } else { 1.0 };
        let data = gridcraft_chart::resolve(&d.wb, psi, &chart);
        gridcraft_chart::render(&chart, &data, size(width), size(height), &gridcraft_chart::ApproxMeasure)
            .into_iter()
            .take(20_000)
            .map(prim)
            .collect()
    }

    fn snapshot(&self) -> Option<(Arc<Workbook>, usize, u64)> {
        let s = self.lock();
        let d = s.active()?;
        Some((d.wb.clone(), d.wb.active_sheet, d.revision))
    }
}

#[uniffi::export]
impl MobileSession {
    #[uniffi::constructor]
    pub fn new() -> Arc<Self> {
        #[cfg(target_os = "android")]
        android_logger::init_once(android_logger::Config::default().with_max_level(log::LevelFilter::Info).with_tag("gridcraft"));
        Arc::new(Self::default())
    }

    /// Open the workbook at `path` (xlsx, xlsm, xls, xlsb, ods, csv, tsv, txt; the extension or
    /// the content decides). The app copies a workbook it was given by URI into its own folder
    /// first. It replaces the workbook open now: the app has one at a time.
    pub fn open(&self, path: String, password: Option<String>) -> Result<WorkbookInfo, MobileError> {
        let mut s = self.lock();
        let given = password.is_some();
        let mut params = json!({ "path": path });
        if let (Some(p), Some(o)) = (password, params.as_object_mut()) {
            o.insert("password".into(), json!(p));
        }
        let before = s.active_index();
        let had = s.documents().len();
        match s.execute("file.open", params) {
            Ok(_) => {
                s.take_ui_requests();
                // one workbook at a time: the one open before goes
                if s.documents().len() > had {
                    s.close_document(before);
                    let last = s.documents().len().saturating_sub(1);
                    s.set_active(last);
                }
                Ok(info(&s))
            }
            Err(e) => {
                s.take_ui_requests();
                let msg = e.to_string();
                Err(if msg.contains(gridcraft_engine::io::PASSWORD_REQUIRED) && !given {
                    MobileError::NeedsPassword
                } else if msg.contains(gridcraft_engine::io::WRONG_PASSWORD) || (given && msg.contains(gridcraft_engine::io::PASSWORD_REQUIRED)) {
                    MobileError::WrongPassword
                } else {
                    MobileError::Open(msg)
                })
            }
        }
    }

    /// A new workbook: blank (`""` or `blank`), or one of the engine's samples (`budget`,
    /// `sales`, `grades`). It replaces the workbook open now.
    pub fn new_workbook(&self, sample: String) -> Result<WorkbookInfo, MobileError> {
        let mut s = self.lock();
        let params = if sample.is_empty() || sample == "blank" { json!({}) } else { json!({ "sample": sample }) };
        // the workbook open now goes first, so a new blank one is Book1 again
        let before = s.documents().len();
        for i in (0..before).rev() {
            s.close_document(i);
        }
        if let Err(e) = Self::run(&mut s, "file.new", params) {
            // never left with nothing open
            if s.documents().is_empty() {
                s.new_workbook();
            }
            return Err(e);
        }
        Ok(info(&s))
    }

    /// Save to `path`, or to the file the workbook came from when `None` (xlsx by default; csv,
    /// tsv, json, html or pdf by extension).
    pub fn save(&self, path: Option<String>) -> Result<WorkbookInfo, MobileError> {
        let mut s = self.lock();
        let params = match path {
            Some(p) => json!({ "path": p }),
            None => json!({}),
        };
        let id = if params.get("path").is_some() { "file.saveAs" } else { "file.save" };
        Self::run(&mut s, id, params).map_err(|e| MobileError::Save(e.to_string()))?;
        Ok(info(&s))
    }

    /// The workbook's title, sheets, revision and undo state.
    pub fn info(&self) -> WorkbookInfo {
        info(&self.lock())
    }

    /// Run the engine command `id` with `params` (a JSON object; empty means `{}`) and return its
    /// result as JSON.
    pub fn execute(&self, id: String, params: String) -> Result<String, MobileError> {
        let params: Json = if params.trim().is_empty() {
            json!({})
        } else {
            serde_json::from_str(&params).map_err(|e| MobileError::Command(format!("{id}: parameters are not JSON: {e}")))?
        };
        let mut s = self.lock();
        Ok(Self::run(&mut s, &id, params)?.to_string())
    }

    /// Whether the command `id` can run now (`None`), or why not.
    pub fn disabled_reason(&self, id: String) -> Option<String> {
        let s = self.lock();
        match gridcraft_engine::find_command(&id) {
            Some(spec) => (spec.enabled)(&s).err(),
            None => Some(format!("unknown command {id}")),
        }
    }

    /// The active sheet's sizes and view settings.
    pub fn sheet_view(&self) -> SheetView {
        let Some((wb, si, _)) = self.snapshot() else { return empty_view() };
        let Some(sh) = wb.sheet(si) else { return empty_view() };
        let used = sh.used_range();
        let (fr, fc) = sh.freeze.unwrap_or((0, 0));
        SheetView {
            default_col_width: sh.default_col_width,
            default_row_height: sh.default_row_height,
            frozen_rows: fr,
            frozen_cols: fc,
            used_rows: used.map_or(0, |u| u.end.row.saturating_add(1)),
            used_cols: used.map_or(0, |u| u.end.col.saturating_add(1)),
            max_rows: MAX_ROWS,
            max_cols: MAX_COLS,
            gridlines: sh.show_gridlines,
            headings: sh.show_headings,
            right_to_left: sh.right_to_left,
            zoom: u32::from(sh.zoom),
            filtered_rows: filtered_rows(sh),
            autofilter: sh.autofilter.is_some(),
            show_formulas: sh.show_formulas,
            row_levels: gridcraft_engine::outline::max_level(&sh.rows),
            col_levels: gridcraft_engine::outline::max_level(&sh.cols),
            row_groups: outline_groups(&sh.rows),
            col_groups: outline_groups(&sh.cols),
        }
    }

    /// Where row `row` starts, from the sheet's top.
    pub fn row_top(&self, row: u32) -> f64 {
        self.snapshot().and_then(|(wb, si, _)| wb.sheet(si).map(|sh| sh.row_top(row.min(MAX_ROWS)))).unwrap_or(0.0)
    }

    /// Where column `col` starts, from the sheet's left.
    pub fn col_left(&self, col: u32) -> f64 {
        self.snapshot().and_then(|(wb, si, _)| wb.sheet(si).map(|sh| sh.col_left(col.min(MAX_COLS)))).unwrap_or(0.0)
    }

    /// The cell under the point (`x`, `y`), from the sheet's top left corner.
    pub fn cell_at(&self, x: f64, y: f64) -> CellAt {
        let finite = |v: f64| if v.is_finite() { v.max(0.0) } else { 0.0 };
        match self.snapshot().and_then(|(wb, si, _)| wb.sheet(si).map(|sh| (sh.row_at(finite(y)), sh.col_at(finite(x))))) {
            Some((row, col)) => CellAt { row, col },
            None => CellAt { row: 0, col: 0 },
        }
    }

    /// The rows `first_row..=last_row` and columns `first_col..=last_col` of the active sheet as
    /// the grid draws them. `digit_width` is the default font's digit width in sheet units at
    /// the app's text size (General numbers are narrowed to fit their column); 0 for the usual.
    pub fn viewport(&self, first_row: u32, first_col: u32, last_row: u32, last_col: u32, digit_width: f32) -> Viewport {
        let Some((wb, si, revision)) = self.snapshot() else {
            return Viewport { sheet: 0, revision: 0, rows: vec![], cols: vec![], cells: vec![], merges: vec![], sparklines: vec![] };
        };
        let digit = if digit_width.is_finite() && digit_width > 0.5 { digit_width } else { DIGIT_WIDTH };
        build_viewport(&wb, si, revision, (first_row, first_col, last_row, last_col), digit)
    }

    /// The selection and what the formula bar shows.
    pub fn selection(&self) -> SelectionView {
        selection_view(&self.lock())
    }

    /// Select the cell at (`row`, `col`), or extend the selection from its anchor to it.
    pub fn select(&self, row: u32, col: u32, extend: bool) -> Result<SelectionView, MobileError> {
        let mut s = self.lock();
        let c = CellRef::new(row.min(MAX_ROWS - 1), col.min(MAX_COLS - 1));
        let params = match s.active() {
            Some(d) if extend => {
                let anchor = d.selection.anchor;
                json!({ "range": RangeRef::new(anchor, c).a1(), "active": anchor.a1() })
            }
            _ => json!({ "range": c.a1() }),
        };
        Self::run(&mut s, "selection.set", params)?;
        Ok(selection_view(&s))
    }

    /// Select the block `range` with the active cell at its first corner: a tapped header (a
    /// whole row or column) or the select-all corner.
    pub fn select_range(&self, range: CellRange) -> Result<SelectionView, MobileError> {
        let mut s = self.lock();
        let clamp = |r: u32, c: u32| CellRef::new(r.min(MAX_ROWS - 1), c.min(MAX_COLS - 1));
        let r = RangeRef::new(clamp(range.first_row, range.first_col), clamp(range.last_row, range.last_col));
        Self::run(&mut s, "selection.set", json!({ "range": r.a1(), "active": r.start.a1() }))?;
        Ok(selection_view(&s))
    }

    /// Put `input` (text, a number or a `=formula`) in the active cell, as the formula bar's
    /// Enter does, then move the selection: `down`, `right`, `up`, `left` or `none`.
    pub fn commit(&self, input: String, then: String) -> Result<SelectionView, MobileError> {
        let mut s = self.lock();
        let cell = s.active().map(|d| d.selection.active.a1()).unwrap_or_else(|| "A1".into());
        Self::run(&mut s, "cell.set", json!({ "cell": cell, "input": input }))?;
        let (dr, dc) = match then.as_str() {
            "down" => (1, 0),
            "up" => (-1, 0),
            "right" => (0, 1),
            "left" => (0, -1),
            _ => (0, 0),
        };
        if (dr, dc) != (0, 0) {
            let single = s.active().is_some_and(|d| d.selection.is_single_cell());
            if single {
                Self::run(&mut s, "selection.move", json!({ "dr": dr, "dc": dc }))?;
            } else {
                // inside a selected block, Enter and Tab go to its next cell
                Self::run(&mut s, "selection.next", json!({ "forward": dr + dc > 0, "byRow": dc != 0 }))?;
            }
        }
        Ok(selection_view(&s))
    }

    /// The active cell's value as number format `code` shows it: the Custom format's sample.
    pub fn format_preview(&self, code: String) -> String {
        let s = self.lock();
        let Some(d) = s.active() else { return String::new() };
        let v = d.wb.active().map(|sh| sh.value(d.selection.active)).unwrap_or_default();
        let code: String = code.chars().take(255).collect();
        let f = gridcraft_engine::numfmt::NumberFormat::parse(&code);
        gridcraft_engine::numfmt::format_value(&v, &f, d.wb.date_system).text.chars().take(200).collect()
    }

    /// The active cell's font, alignment and number format.
    pub fn cell_format(&self) -> CellFormat {
        let s = self.lock();
        let Some(d) = s.active() else { return cell_format(&Style::default(), false) };
        let c = d.selection.active;
        match d.wb.active() {
            Some(sh) => CellFormat {
                // the sheet keeps pixels (96 to the inch)
                row_height: sh.row_height(c.row) * 0.75,
                col_width: gridcraft_engine::cmd::format::points_to_chars(f64::from(sh.col_width(c.col))) as f32,
                ..cell_format(d.wb.styles.get(sh.style_id(c)), sh.merge_at(c).is_some())
            },
            None => cell_format(&Style::default(), false),
        }
    }

    /// The encoded bytes (PNG, JPEG…) of the picture placed in cell (`row`, `col`) of the active sheet.
    pub fn cell_picture(&self, row: u32, col: u32) -> Option<Vec<u8>> {
        let (wb, si, _) = self.snapshot()?;
        wb.sheet(si)?.cell_pictures.get(&CellRef::new(row.min(MAX_ROWS - 1), col.min(MAX_COLS - 1))).map(|p| p.data.clone())
    }

    /// How each of the cell styles [names] looks in the workbook's theme (unknown names are left out).
    pub fn cell_style_tiles(&self, names: Vec<String>) -> Vec<StyleTile> {
        let (theme, cell) = {
            let s = self.lock();
            let d = s.active();
            let theme = d.map(|d| d.wb.theme.clone()).unwrap_or_default();
            let cell = d.and_then(|d| d.wb.active().map(|sh| d.wb.styles.get(sh.style_id(d.selection.active)).clone()));
            (theme, cell)
        };
        let mut matched = false;
        let line = |l: &BorderLine| {
            (l.style != BorderStyle::None).then(|| TileLine { style: border_name(l.style), argb: argb(l.color.resolve(&theme).unwrap_or([0, 0, 0])) })
        };
        names
            .into_iter()
            .filter_map(|name| {
                let st = gridcraft_engine::cmd::format::builtin_cell_style(&name, &theme)?;
                let chosen = !matched && cell.as_ref().is_some_and(|c| looks_like(c, &st));
                matched |= chosen;
                let b = &st.borders;
                let boxed = b.top == b.bottom && b.left == b.right && b.top == b.left && b.top.style != BorderStyle::None;
                Some(StyleTile {
                    fill: (st.fill.pattern == PatternType::Solid).then(|| st.fill.fg.resolve(&theme)).flatten().map(argb),
                    text: argb(st.font.color.resolve(&theme).unwrap_or([0, 0, 0])),
                    bold: st.font.bold,
                    italic: st.font.italic,
                    size: st.font.size,
                    around: if boxed { line(&b.top) } else { None },
                    top: if boxed { None } else { line(&b.top) },
                    bottom: if boxed { None } else { line(&b.bottom) },
                    chosen,
                    name,
                })
            })
            .collect()
    }

    /// The charts, pictures and shapes on the active sheet, in drawing order.
    pub fn objects(&self) -> Vec<SheetObject> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(sh) = wb.sheet(si) else { return vec![] };
        let place = |a: &gridcraft_engine::model::Anchor| {
            let c = a.cell;
            let x = sh.col_left(c.col.min(MAX_COLS)) + f64::from(a.dx);
            let y = sh.row_top(c.row.min(MAX_ROWS)) + f64::from(a.dy);
            let finite = |v: f64| if v.is_finite() { v.max(0.0) } else { 0.0 };
            (finite(x), finite(y), finite(f64::from(a.width)), finite(f64::from(a.height)))
        };
        let index = |i: usize| u32::try_from(i).unwrap_or(u32::MAX);
        let mut out = Vec::new();
        for (i, sp) in sh.shapes.iter().enumerate() {
            let (x, y, width, height) = place(&sp.anchor);
            let kind = format!("{:?}", sp.kind);
            let shape = kind.chars().next().map(|f| f.to_ascii_lowercase().to_string() + &kind[f.len_utf8()..]).unwrap_or_default();
            out.push(SheetObject {
                kind: "shape".into(),
                index: index(i),
                id: sp.id,
                x,
                y,
                width,
                height,
                shape,
                // a see-through fill carries its opacity in the alpha byte
                fill: sp.fill.resolve(&wb.theme).map(|c| with_alpha(argb(c), 1.0 - sp.format.fill_transparency)),
                line: if sp.format.no_line { None } else { sp.line.resolve(&wb.theme).map(argb) },
                text: sp.text.chars().take(10_000).collect(),
                alt: sp.format.alt.clone(),
                crop: vec![0.0, 0.0, 1.0, 1.0],
                line_width: 0.0,
                shadow: None,
                reflection: None,
                line_parts: vec![],
                line_miter: false,
                soft_edge: 0.0,
                view_turn: 0.0,
                rotation: sp.format.turn.rotation,
                flip_h: sp.format.turn.flip_h,
                flip_v: sp.format.turn.flip_v,
                pieces: {
                    use gridcraft_engine::model::ShapeKind as K;
                    let (w, h) = (width as f32, height as f32);
                    let (start, end) = sp.arrow_ends();
                    let name = match sp.kind {
                        K::Rectangle => "rect",
                        K::RoundedRectangle => "roundRect",
                        K::Ellipse => "ellipse",
                        K::Triangle => "triangle",
                        K::Line | K::Arrow => "line",
                        K::Preset => sp.format.preset.as_str(),
                        K::TextBox | K::Icon | K::Ink => "",
                    };
                    // a preset GridCraft doesn't draw (kept from a file) shows as its box
                    let pieces = match name {
                        "" => None,
                        n => gridcraft_chart::shapes::shape(n, w, h, start, end).or_else(|| gridcraft_chart::shapes::preset("rect", w, h)),
                    };
                    pieces.map(|p| shape_pieces(&p, 1.0, 0.0, 0.0)).unwrap_or_default()
                },
                text_color: sp.format.text_color.and_then(|c| c.resolve(&wb.theme)).map(argb),
                text_align: match sp.format.align.unwrap_or_default() {
                    ShapeTextAlign::Left => "left",
                    ShapeTextAlign::Center => "center",
                    ShapeTextAlign::Right => "right",
                }
                .into(),
                text_anchor: match sp.format.anchor.unwrap_or_default() {
                    ShapeTextAnchor::Top => "top",
                    ShapeTextAnchor::Middle => "middle",
                    ShapeTextAnchor::Bottom => "bottom",
                }
                .into(),
                preset: sp.format.preset.clone(),
                gradient_colors: sp.format.gradient.iter().map(|g| color_or(g.color, &wb, [0, 0, 0])).collect(),
                gradient_stops: sp.format.gradient.iter().map(|g| g.pos).collect(),
                gradient_angle: sp.format.gradient_angle,
                decorative: sh.decorative.contains(&sp.id),
                text_bold: sp.format.bold,
                text_italic: sp.format.italic,
                text_underline: sp.format.underline,
                text_size: sp.format.font_size.filter(|v| v.is_finite()).unwrap_or(0.0),
            });
        }
        for (i, im) in sh.images.iter().enumerate() {
            out.push(image_object(im, index(i), place(&im.anchor), sh.decorative.contains(&im.id), &wb.theme));
        }
        for (i, ch) in sh.charts.iter().enumerate() {
            let (x, y, width, height) = place(&ch.anchor);
            out.push(SheetObject {
                kind: "chart".into(),
                index: index(i),
                id: ch.id,
                x,
                y,
                width,
                height,
                shape: String::new(),
                fill: None,
                line: None,
                text: ch.title.clone().unwrap_or_default(),
                alt: ch.alt.clone(),
                crop: vec![0.0, 0.0, 1.0, 1.0],
                line_width: 0.0,
                shadow: None,
                reflection: None,
                line_parts: vec![],
                line_miter: false,
                soft_edge: 0.0,
                view_turn: 0.0,
                rotation: 0.0,
                flip_h: false,
                flip_v: false,
                pieces: vec![],
                text_color: None,
                text_align: String::new(),
                text_anchor: String::new(),
                preset: String::new(),
                gradient_colors: vec![],
                gradient_stops: vec![],
                gradient_angle: 0.0,
                decorative: sh.decorative.contains(&ch.id),
                text_bold: false,
                text_italic: false,
                text_underline: false,
                text_size: 0.0,
            });
        }
        out
    }

    /// Chart `index` of the active sheet laid out at `width` × `height` (its own units, the
    /// size it is drawn at), as drawing steps.
    pub fn chart_prims(&self, index: u32, width: f32, height: f32) -> Vec<ChartPrim> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(chart) = wb.sheet(si).and_then(|sh| sh.charts.get(index as usize)) else { return vec![] };
        let size = |v: f32| if v.is_finite() { v.clamp(1.0, 8192.0) } else { 1.0 };
        let data = gridcraft_chart::resolve(&wb, si, chart);
        gridcraft_chart::render(chart, &data, size(width), size(height), &gridcraft_chart::ApproxMeasure)
            .into_iter()
            .take(100_000)
            .map(prim)
            .collect()
    }

    /// A chart of kind `kind` (`type|subtype`, the Insert › Chart names) drawn `width` × `height`
    /// over sample data of our own (two categories of three series, or what the kind needs), for
    /// the chart galleries. Empty for a kind the engine doesn't make.
    pub fn chart_preview(&self, kind: String, width: f32, height: f32) -> Vec<ChartPrim> {
        let (t, sub) = kind.split_once('|').unwrap_or((kind.as_str(), ""));
        let values = match t {
            // a pie of pie or bar of pie shows its split with a few more points
            "pie" if matches!(sub, "pieOfPie" | "barOfPie") => json!([["", "Series1"], ["A", 38], ["B", 26], ["C", 18], ["D", 10], ["E", 8]]),
            "scatter" => json!([["X", "Y"], [1, 2.2], [2, 3.9], [3, 3.1], [4, 4.6], [5, 4.0]]),
            "bubble" => json!([["X", "Y", "Size"], [1, 2.2, 3], [2, 3.9, 6], [3, 3.1, 4], [4, 4.6, 8]]),
            "histogram" if sub == "pareto" => json!([["", "Count"], ["A", 18], ["B", 42], ["C", 9], ["D", 25], ["E", 5]]),
            "histogram" | "boxWhisker" => json!([["Value"], [12], [15], [17], [21], [22], [24], [26], [27], [31], [33], [36], [41]]),
            "surface" => json!([
                ["", "Series1", "Series2", "Series3"],
                ["Category 1", 4.3, 2.4, 2],
                ["Category 2", 2.5, 4.4, 2],
                ["Category 3", 3.5, 1.8, 3],
                ["Category 4", 4.5, 2.8, 5],
            ]),
            // the chart adds the total itself
            "waterfall" => json!([["", "Change"], ["Start", 50], ["Up", 20], ["Down", -15], ["Up", 12]]),
            "funnel" => json!([["", "Count"], ["Stage 1", 100], ["Stage 2", 72], ["Stage 3", 48], ["Stage 4", 25]]),
            "treemap" | "sunburst" => json!([["", "Size"], ["A", 45], ["B", 28], ["C", 17], ["D", 10], ["E", 6]]),
            "radar" => json!([
                ["", "Series1", "Series2", "Series3"],
                ["Category 1", 4.2, 2.5, 1.9],
                ["Category 2", 2.6, 4.3, 2.1],
                ["Category 3", 3.4, 1.8, 3.0],
                ["Category 4", 4.5, 2.8, 4.8],
                ["Category 5", 3.1, 3.6, 2.4],
            ]),
            _ => json!([["", "Series1", "Series2", "Series3"], ["Category 1", 4.2, 2.5, 1.9], ["Category 2", 2.6, 4.3, 2.1]]),
        };
        let rows = values.as_array().map_or(0, Vec::len);
        let cols = values.get(0).and_then(Json::as_array).map_or(0, Vec::len);
        let range = RangeRef::new(CellRef::new(0, 0), CellRef::new(rows.saturating_sub(1) as u32, cols.saturating_sub(1) as u32)).a1();
        let mut s = Session::new();
        s.new_workbook();
        let mut p = json!({ "range": range, "type": t, "title": "Chart Title" });
        if !sub.is_empty() {
            p["subtype"] = json!(sub);
        }
        if s.run("range.setValues", json!({ "range": "A1", "values": values })).is_err() || s.run("insert.chart", p).is_err() {
            return vec![];
        }
        let Some(d) = s.active() else { return vec![] };
        let si = d.wb.active_sheet;
        let Some(chart) = d.wb.sheet(si).and_then(|sh| sh.charts.first()) else { return vec![] };
        let size = |v: f32| if v.is_finite() { v.clamp(1.0, 4096.0) } else { 1.0 };
        let data = gridcraft_chart::resolve(&d.wb, si, chart);
        gridcraft_chart::render(chart, &data, size(width), size(height), &gridcraft_chart::ApproxMeasure).into_iter().take(20_000).map(prim).collect()
    }

    /// The Layout gallery's preview of layout `layout` for chart `id`: a chart of its type, colours
    /// and title over sample data like the other galleries' (four quarters for a pie), laid out that
    /// way. Empty past its layouts.
    pub fn chart_layout_preview(&self, id: u32, layout: u32, width: f32, height: f32) -> Vec<ChartPrim> {
        self.chart_sample(id, "chart.quickLayout", json!({ "layout": layout }), width, height)
    }

    /// The Style page's preview of style `style` for chart `id`, as the Layout gallery's.
    pub fn chart_style_preview(&self, id: u32, style: u32, width: f32, height: f32) -> Vec<ChartPrim> {
        self.chart_sample(id, "chart.style", json!({ "style": style }), width, height)
    }

    /// Chart `id`'s source on the active sheet: each series' name and values and the categories
    /// (once), where they are cells of this sheet.
    pub fn chart_source(&self, id: u32) -> Vec<ChartSourceBlock> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(sh) = wb.sheet(si) else { return vec![] };
        let Some(ch) = sh.charts.iter().find(|c| c.id == id) else { return vec![] };
        // a reference to cells of this sheet (its own name or none)
        let here = |f: &str| -> Option<RangeRef> {
            let f = f.trim().trim_start_matches('=');
            let (name, body) = match f.rsplit_once('!') {
                Some((n, b)) => (Some(n.trim_matches('\'').replace("''", "'")), b),
                None => (None, f),
            };
            if name.is_some_and(|n| !n.eq_ignore_ascii_case(&sh.name)) {
                return None;
            }
            RangeRef::parse(&body.replace('$', ""))
        };
        let block = |role: &str, series: usize, r: RangeRef| ChartSourceBlock {
            role: role.into(),
            series: series as u32,
            first_row: r.start.row,
            first_col: r.start.col,
            last_row: r.end.row,
            last_col: r.end.col,
        };
        let mut out = Vec::new();
        if let Some(r) = ch.series.iter().find_map(|se| se.categories.as_deref().and_then(here)) {
            out.push(block("categories", 0, r));
        }
        for (i, se) in ch.series.iter().enumerate().take(64) {
            if let Some(r) = se.name.as_deref().and_then(here) {
                out.push(block("name", i, r));
            }
            if let Some(r) = here(&se.values) {
                out.push(block("values", i, r));
            }
        }
        out
    }

    /// The chart Color page's palettes, Colorful then Monochromatic, each as six series take it.
    pub fn chart_palettes(&self) -> Vec<ChartPalette> {
        let theme = self.snapshot().map(|(wb, _, _)| wb.theme.clone()).unwrap_or_default();
        gridcraft_engine::model::chart_palette::PALETTES
            .iter()
            .map(|(id, name)| ChartPalette {
                id: *id,
                param: if *id <= 13 { format!("colorful{}", id - 9) } else { format!("monochromatic{}", id - 13) },
                name: (*name).into(),
                colors: (0..6)
                    .map(|i| {
                        let [r, g, b, _] = gridcraft_chart::palette_color(&theme, *id, i, 6);
                        argb([r, g, b])
                    })
                    .collect(),
            })
            .collect()
    }

    /// Picture Styles' gallery: each style's name shown and what `picture.style` takes as `style`.
    pub fn picture_styles(&self) -> Vec<ShapeTile> {
        gridcraft_engine::picture_styles::PICTURE_STYLES.iter().map(|(label, id)| ShapeTile { label: (*label).into(), kind: (*id).into() }).collect()
    }

    /// Picture style `id` on a picture `width`×`height`, as the sheet would show it: for its
    /// gallery tile.
    pub fn picture_style_tile(&self, id: String, width: f64, height: f64) -> Option<SheetObject> {
        let look = gridcraft_engine::picture_styles::picture_style(&id)?;
        let size = |v: f64| if v.is_finite() { v.clamp(1.0, 4096.0) } else { 1.0 };
        let im = gridcraft_engine::model::Image {
            id: 0,
            anchor: Default::default(),
            data: vec![],
            mime: String::new(),
            alt: String::new(),
            turn: Default::default(),
            crop: Default::default(),
            look,
        };
        Some(image_object(&im, 0, (0.0, 0.0, size(width), size(height)), false, &gridcraft_engine::model::Theme::default()))
    }

    /// Picture Effects' shadow `name` (`offsetBottomRight`, `insideTop`, `perspectiveBelow`…) as
    /// the screen draws it, for its gallery tile.
    pub fn shadow_preset(&self, name: String) -> Option<ObjectShadow> {
        gridcraft_engine::model::Shadow::preset(&name).map(|sh| object_shadow(sh, &gridcraft_engine::model::Theme::default()))
    }

    /// Picture Effects' reflection `name` (`tightTouching`, `half4pt`…), for its gallery tile.
    pub fn reflection_preset(&self, name: String) -> Option<ObjectReflection> {
        gridcraft_engine::model::Reflection::preset(&name).map(object_reflection)
    }

    /// The Shapes gallery: its bands and their shapes.
    pub fn shape_gallery(&self) -> Vec<ShapeBand> {
        gridcraft_chart::shapes::GALLERY
            .iter()
            .map(|(band, shapes)| ShapeBand {
                name: (*band).into(),
                shapes: shapes.iter().map(|(label, kind)| ShapeTile { label: (*label).into(), kind: (*kind).into() }).collect(),
            })
            .collect()
    }

    /// Shape `kind` (a gallery name) drawn to fit a `width`×`height` tile, at its own proportions,
    /// a little in from the edges.
    pub fn shape_preview(&self, kind: String, width: f32, height: f32) -> Vec<ShapePiece> {
        use gridcraft_chart::shapes;
        let size = |v: f32| if v.is_finite() { v.clamp(1.0, 4096.0) } else { 1.0 };
        let (tw, th) = (size(width), size(height));
        // drawn at about the tile's size, so its arrowheads keep their size beside it
        let (dw, dh) = shapes::default_size(&kind);
        let k = tw.max(th) / dw.max(dh).max(1.0);
        let (w, h) = (dw * k, dh * k);
        let Some(pieces) = shapes::preset(&kind, w, h) else { return vec![] };
        // fit what is drawn (callouts reach out of their box)
        let b = shapes::bounds(&pieces);
        let (bw, bh) = ((b[2] - b[0]).max(1e-3), (b[3] - b[1]).max(1e-3));
        let scale = (tw * 0.9 / bw).min(th * 0.9 / bh);
        let (dx, dy) = ((tw - bw * scale) / 2.0 - b[0] * scale, (th - bh * scale) / 2.0 - b[1] * scale);
        shape_pieces(&pieces, scale, dx, dy)
    }

    /// Picture `index` of the active sheet, encoded (PNG or JPEG).
    /// The picture's own size in pixels (width, height), from its encoded bytes.
    pub fn image_size(&self, index: u32) -> Option<Vec<u32>> {
        let (wb, si, _) = self.snapshot()?;
        let (w, h) = gridcraft_engine::io::image_size(&wb.sheet(si)?.images.get(index as usize)?.data)?;
        Some(vec![w, h])
    }

    pub fn image_bytes(&self, index: u32) -> Option<Vec<u8>> {
        let (wb, si, _) = self.snapshot()?;
        Some(wb.sheet(si)?.images.get(index as usize)?.data.clone())
    }

    /// The values of the filter column at (`row`, `col`) (a filter's or a table's header cell),
    /// for its filter list. A table gets its filter when it is first asked for.
    pub fn filter_column(&self, row: u32, col: u32) -> Vec<FilterValue> {
        let mut s = self.lock();
        let Some(d) = s.active() else { return vec![] };
        let si = d.wb.active_sheet;
        let c = CellRef::new(row.min(MAX_ROWS - 1), col.min(MAX_COLS - 1));
        // a table's filter covers its header and data rows, not its totals row
        let table = d.wb.active().and_then(|sh| {
            if sh.autofilter.is_some() {
                return None;
            }
            let t = sh.table_at(c)?;
            let end = t.data_range().map_or(t.range.end, |r| r.end);
            Some(RangeRef::new(t.range.start, end))
        });
        if let Some(r) = table {
            // a table's header buttons filter through the sheet's filter, made over the table
            if let Some(d) = s.active_mut() {
                let wb = Arc::make_mut(&mut d.wb);
                if let Some(sh) = wb.sheet_mut(si) {
                    sh.autofilter = Some(gridcraft_engine::model::AutoFilter { range: r, criteria: vec![] });
                }
            }
        }
        let Some(d) = s.active() else { return vec![] };
        gridcraft_engine::cmd::data::filter_values(&d.wb, si, c.col)
            .into_iter()
            .take(10_000)
            .map(|(text, shown)| FilterValue { text, shown })
            .collect()
    }

    /// The fills of filter column `col`'s cells (No Fill first), for the filter sheet's Color tab;
    /// call after [`Self::filter_column`].
    pub fn filter_fills(&self, col: u32) -> Vec<FilterFill> {
        let s = self.lock();
        let Some(d) = s.active() else { return vec![] };
        let wb = &d.wb;
        gridcraft_engine::cmd::data::filter_fills(wb, wb.active_sheet, col.min(MAX_COLS - 1))
            .into_iter()
            .map(|(c, chosen)| {
                let param = match c {
                    Color::Auto => json!("none"),
                    Color::Rgb(v) => json!(format!("#{:06X}", v & 0xFF_FFFF)),
                    Color::Theme(i, tint) => json!({"theme": i, "tint": f64::from(tint) / 1000.0}),
                };
                FilterFill { color: (c != Color::Auto).then(|| c.resolve(&wb.theme)).flatten().map(argb), param: param.to_string(), chosen }
            })
            .collect()
    }

    /// The table the active cell is in, if any.
    pub fn table_info(&self) -> Option<TableInfo> {
        let s = self.lock();
        let d = s.active()?;
        let c = d.selection.active;
        let t = d.wb.active()?.table_at(c)?;
        let total = (t.totals_row && c.row == t.range.end.row).then(|| t.columns.get((c.col - t.range.start.col) as usize)).flatten();
        let total_function = match total.map(|col| col.totals) {
            Some(TotalsFn::Average) => "average",
            Some(TotalsFn::Count) => "count",
            Some(TotalsFn::CountNums) => "countNums",
            Some(TotalsFn::Max) => "max",
            Some(TotalsFn::Min) => "min",
            Some(TotalsFn::Sum) => "sum",
            Some(TotalsFn::StdDev) => "stdDev",
            Some(TotalsFn::Var) => "var",
            _ => "",
        };
        Some(TableInfo {
            name: t.name.clone(),
            style: t.style.clone(),
            header_row: t.header_row,
            totals_row: t.totals_row,
            banded_rows: t.banded_rows,
            banded_cols: t.banded_cols,
            first_col: t.first_col,
            last_col: t.last_col,
            range: t.range.into(),
            in_header: t.header_row && c.row == t.range.start.row,
            total_column: total.map(|col| col.name.clone()),
            total_function: total_function.into(),
            alt_text: t.alt_text.clone(),
        })
    }

    /// The table the active cell is in, as cards: at most 5,000 rows of 100 fields, each value cut
    /// to 1,000 characters.
    pub fn table_cards(&self) -> Option<TableCards> {
        let s = self.lock();
        let d = s.active()?;
        let sh = d.wb.active()?;
        let t = sh.table_at(d.selection.active)?;
        let first = t.range.start.col;
        let last = t.range.end.col.min(first.saturating_add(MAX_CARD_FIELDS - 1));
        let fields = (first..=last)
            .enumerate()
            .map(|(i, c)| {
                t.columns.get(i).map(|col| col.name.clone()).unwrap_or_else(|| {
                    // a table without a header row still names its columns
                    format!("Column{}", c - first + 1)
                })
            })
            .collect();
        let mut cards = Vec::new();
        let mut more = false;
        if let Some(data) = t.data_range() {
            for row in data.start.row..=data.end.row {
                if sh.is_row_hidden(row) {
                    continue;
                }
                if cards.len() >= MAX_CARDS {
                    more = true;
                    break;
                }
                let values = (first..=last)
                    .map(|c| gridcraft_engine::display::cell_text(&d.wb, sh, CellRef::new(row, c)).chars().take(1_000).collect())
                    .collect();
                cards.push(TableCard { row, values });
            }
        }
        Some(TableCards { name: t.name.clone(), fields, first_col: first, cards, more })
    }

    /// The table styles, no style first and then light to dark, as samples in the workbook's theme.
    pub fn table_styles(&self) -> Vec<TableStylePreview> {
        let theme = self.snapshot().map(|(wb, _, _)| wb.theme.clone()).unwrap_or_default();
        let mut wb = Workbook::new();
        wb.theme = theme;
        std::iter::once(String::new())
            .chain(gridcraft_engine::tables::gallery())
            .map(|name| {
                let cells = gridcraft_engine::tables::sample(&wb, &name)
                    .into_iter()
                    .map(|st| TileCell {
                        fill: if st.fill.pattern == PatternType::None { None } else { st.fill.fg.resolve(&wb.theme).map(argb) },
                        text: color_or(st.font.color, &wb, [0, 0, 0]),
                        left: edge(st.borders.left, &wb),
                        top: edge(st.borders.top, &wb),
                        right: edge(st.borders.right, &wb),
                        bottom: edge(st.borders.bottom, &wb),
                    })
                    .collect();
                TableStylePreview { name, cells }
            })
            .collect()
    }

    /// The aggregate bar's figures, for a selection of more than one cell (`None` for one cell).
    pub fn selection_stats(&self) -> Option<SelectionStats> {
        let (wb, sel) = {
            let s = self.lock();
            let d = s.active()?;
            (d.wb.clone(), d.selection.clone())
        };
        if sel.ranges.len() == 1 && sel.is_single_cell() {
            return None;
        }
        let sh = wb.active()?;
        let st = gridcraft_engine::display::stats(sh, &sel.ranges);
        let code = wb.styles.get(sh.style_id(sel.active)).num_fmt.clone();
        // in the active cell's format; a General one rounded to four decimals, as the phone app's
        // chips show 403/12 as 33.5833
        let general = code.as_str().is_empty() || code.as_str().eq_ignore_ascii_case("General");
        let shown = |n: f64| {
            let n = if general && n.is_finite() && n.abs() < 1e15 { (n * 10_000.0).round() / 10_000.0 } else { n };
            gridcraft_engine::display::format(&Value::Number(n), code.as_str(), &wb).text
        };
        Some(SelectionStats {
            count: st.count,
            numeric: st.numeric,
            sum: if st.numeric > 0 { shown(st.sum) } else { String::new() },
            average: st.average.map(shown).unwrap_or_default(),
            max: if st.numeric > 0 { shown(st.max) } else { String::new() },
            min: if st.numeric > 0 { shown(st.min) } else { String::new() },
        })
    }

    /// The active cell's data validation list and input message, if it has either.
    pub fn validation(&self) -> Option<ValidationView> {
        let s = self.lock();
        let d = s.active()?;
        let si = d.wb.active_sheet;
        let c = d.selection.active;
        let dv = d.wb.active()?.validations.iter().find(|v| v.ranges.iter().any(|r| r.contains(c)))?;
        let items = if dv.kind == gridcraft_engine::model::ValidationKind::List && dv.in_cell_dropdown {
            gridcraft_engine::cmd::data::list_items(&d.wb, si, dv).into_iter().take(10_000).collect()
        } else {
            vec![]
        };
        let (title, message) = if dv.show_input { (dv.input_title.clone(), dv.input_message.clone()) } else { (String::new(), String::new()) };
        if items.is_empty() && message.is_empty() && title.is_empty() {
            return None;
        }
        Some(ValidationView { items, title, message })
    }

    /// What the active cell's data validation says to `input`, or `None` when it allows it.
    pub fn check_entry(&self, input: String) -> Option<EntryAlert> {
        use gridcraft_engine::model::ErrorStyle;
        let s = self.lock();
        let d = s.active()?;
        let (dv, message) = gridcraft_engine::cmd::data::check_validation(&d.wb, d.wb.active_sheet, d.selection.active, &input)?;
        let style = match dv.error_style {
            ErrorStyle::Stop => "stop",
            ErrorStyle::Warning => "warning",
            ErrorStyle::Information => "information",
        };
        Some(EntryAlert { style: style.into(), title: dv.error_title, message })
    }

    /// The active cell's data validation rule, if it has one.
    pub fn validation_rule(&self) -> Option<ValidationRule> {
        use gridcraft_engine::model::{CfOperator as Op, ErrorStyle, ValidationKind as K};
        let s = self.lock();
        let d = s.active()?;
        let c = d.selection.active;
        let sys = d.wb.date_system;
        let dv = d.wb.active()?.validations.iter().find(|v| v.ranges.iter().any(|r| r.contains(c)))?;
        let shown = |f: &str| -> String {
            let f = f.trim();
            if dv.kind == K::List && f.starts_with('"') {
                return f.trim_matches('"').to_string();
            }
            if matches!(dv.kind, K::Date | K::Time)
                && let Ok(n) = f.parse::<f64>()
                && let Some(t) = gridcraft_engine::core::date::datetime_from_serial(sys, n)
            {
                return if dv.kind == K::Date { format!("{:04}-{:02}-{:02}", t.year, t.month, t.day) } else { format!("{}:{:02}", t.hour, t.minute) };
            }
            f.to_string()
        };
        Some(ValidationRule {
            kind: match dv.kind {
                K::Any => "any",
                K::Whole => "whole",
                K::Decimal => "decimal",
                K::List => "list",
                K::Date => "date",
                K::Time => "time",
                K::TextLength => "textLength",
                K::Custom => "custom",
            }
            .into(),
            operator: match dv.op {
                Op::Between => "between",
                Op::NotBetween => "notBetween",
                Op::Equal => "equal",
                Op::NotEqual => "notEqual",
                Op::Greater => "greater",
                Op::Less => "less",
                Op::GreaterOrEqual => "greaterOrEqual",
                Op::LessOrEqual => "lessOrEqual",
            }
            .into(),
            formula1: shown(&dv.f1),
            formula2: dv.f2.as_deref().map(shown).unwrap_or_default(),
            ignore_blank: dv.allow_blank,
            dropdown: dv.in_cell_dropdown,
            input_title: dv.input_title.clone(),
            input_message: dv.input_message.clone(),
            error_style: match dv.error_style {
                ErrorStyle::Stop => "stop",
                ErrorStyle::Warning => "warning",
                ErrorStyle::Information => "information",
            }
            .into(),
            error_title: dv.error_title.clone(),
            error_message: dv.error_message.clone(),
        })
    }

    /// The lines of text in columns `first_col..=last_col` of the active sheet, for autofit to
    /// measure (merged cells are left out, as autofit leaves them).
    pub fn fit_texts(&self, first_col: u32, last_col: u32) -> Vec<FitText> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(sh) = wb.sheet(si) else { return vec![] };
        let Some(u) = sh.used_range() else { return vec![] };
        let (a, b) = (first_col.min(MAX_COLS), last_col.min(MAX_COLS));
        let (a, b) = (a.max(u.start.col), b.min(u.end.col));
        let mut out = Vec::new();
        for c in a..=b {
            let col = RangeRef::new(CellRef::new(u.start.row, c), CellRef::new(u.end.row, c));
            for (cell, _) in sh.cells.iter_range(col) {
                if sh.merge_at(cell).is_some_and(|m| !m.is_single()) {
                    continue;
                }
                let st = wb.styles.get(sh.style_id(cell));
                let text = gridcraft_engine::display::cell_text(&wb, sh, cell);
                let extra = 6.0 + f32::from(st.align.indent) * 9.0 + sh.filter_button_space(cell);
                for line in text.lines().filter(|l| !l.is_empty()) {
                    out.push(FitText {
                        col: c,
                        text: line.chars().take(2_000).collect(),
                        font: st.font.name.clone(),
                        size: st.font.size,
                        bold: st.font.bold,
                        italic: st.font.italic,
                        extra,
                    });
                    if out.len() >= 100_000 {
                        return out;
                    }
                }
            }
        }
        out
    }

    /// The PivotTable the active cell is in, if any.
    pub fn pivot_info(&self) -> Option<PivotInfo> {
        let s = self.lock();
        let d = s.active()?;
        let at = d.selection.active;
        let pt = d.wb.active()?.pivots.iter().find(|pt| pt.last_range.is_some_and(|r| r.contains(at)))?;
        Some(PivotInfo {
            name: pt.name.clone(),
            layout: match pt.layout {
                gridcraft_engine::model::PivotLayout::Compact => "compact",
                gridcraft_engine::model::PivotLayout::Outline => "outline",
                gridcraft_engine::model::PivotLayout::Tabular => "tabular",
            }
            .into(),
            grand_totals_rows: pt.grand_totals_rows,
            grand_totals_cols: pt.grand_totals_cols,
            subtotals: if !pt.subtotals {
                "none"
            } else if pt.subtotals_top {
                "top"
            } else {
                "bottom"
            }
            .into(),
            style: pt.style.clone(),
            show_headers: pt.show_headers,
        })
    }

    /// What the chart with id `id` on the active sheet shows.
    pub fn chart_info(&self, id: u32) -> Option<ChartInfo> {
        use gridcraft_engine::model::{ChartKind, ErrorAmount, LabelPos, LegendPos, TrendlineKind};
        let s = self.lock();
        let ch = s.active()?.wb.active()?.charts.iter().find(|c| c.id == id)?.clone();
        let trendline = match ch.series.first().and_then(|se| se.trendlines.first()) {
            None => "none",
            Some(t) => match t.kind {
                TrendlineKind::Linear if t.forward > 0.0 => "linearForecast",
                TrendlineKind::Linear => "linear",
                TrendlineKind::Exponential => "exponential",
                TrendlineKind::MovingAverage(_) => "movingAverage",
                _ => "other",
            },
        };
        Some(ChartInfo {
            kind: format!("{:?}", ch.kind),
            title: ch.title.as_deref().is_some_and(|t| !t.is_empty()),
            legend: match ch.legend {
                LegendPos::None => "none",
                LegendPos::Bottom => "bottom",
                LegendPos::Top => "top",
                LegendPos::Left => "left",
                LegendPos::Right => "right",
            }
            .into(),
            data_labels: ch.data_labels,
            gridlines: ch.gridlines,
            axis_titles: ch.x_title.is_some() || ch.y_title.is_some(),
            trendline: trendline.into(),
            title_overlay: ch.elements.title_overlay,
            label_position: match ch.elements.label_pos {
                LabelPos::Auto => "auto",
                LabelPos::Center => "center",
                LabelPos::InsideEnd => "insideEnd",
                LabelPos::InsideBase => "insideBase",
                LabelPos::OutsideEnd => "outsideEnd",
                LabelPos::BestFit => "bestFit",
                LabelPos::Left => "left",
                LabelPos::Right => "right",
                LabelPos::Above => "above",
                LabelPos::Below => "below",
            }
            .into(),
            error_bars: match ch.elements.error_bars {
                None => "none",
                Some(ErrorAmount::StandardError) => "standardError",
                Some(ErrorAmount::Percent(_)) => "percentage",
                Some(ErrorAmount::StdDev(_)) => "standardDeviation",
                Some(ErrorAmount::Fixed(_)) => "fixed",
            }
            .into(),
            up_down_bars: ch.elements.up_down_bars,
            lines: if ch.kind == ChartKind::Stock {
                match (ch.elements.drop_lines, ch.elements.no_hi_lo) {
                    (true, false) => "dropHighLow",
                    (false, false) => "highLow",
                    (true, true) => "drop",
                    (false, true) => "none",
                }
            } else if ch.elements.high_low_lines {
                "highLow"
            } else if ch.elements.drop_lines {
                "drop"
            } else {
                "none"
            }
            .into(),
            data_table: ch.elements.data_table,
            palette: if ch.elements.palette == 0 { gridcraft_engine::model::chart_palette::AUTOMATIC } else { ch.elements.palette },
            source: ch.source.clone().unwrap_or_default(),
            has_axes: !matches!(
                ch.kind,
                ChartKind::Pie | ChartKind::PieOfPie | ChartKind::BarOfPie | ChartKind::Doughnut | ChartKind::Treemap | ChartKind::Sunburst
            ),
            horizontal: matches!(ch.kind, ChartKind::BarClustered | ChartKind::BarStacked | ChartKind::BarStacked100),
            deep: ch.depth != gridcraft_engine::model::Depth::Flat,
            cat_axis: !ch.elements.hide_cat_axis,
            val_axis: !ch.elements.hide_val_axis,
            cat_axis_title: ch.x_title.is_some(),
            val_axis_title: ch.y_title.is_some(),
            cat_gridlines: ch.elements.cat_gridlines,
            minor_val_gridlines: ch.elements.minor_val_gridlines,
            minor_cat_gridlines: ch.elements.minor_cat_gridlines,
            data_table_keys: !ch.elements.data_table_no_keys,
            layouts: gridcraft_engine::cmd::extra::quick_layouts(ch.kind, ch.depth),
            style: gridcraft_engine::model::chart_style::styles_of(ch.kind, ch.depth)
                .iter()
                .position(|st| st.id == ch.elements.style)
                .map_or(0, |i| i as u32 + 1),
            styles: gridcraft_engine::model::chart_style::styles_of(ch.kind, ch.depth).len() as u32,
        })
    }

    /// The note or comment thread on the active cell, if any.
    pub fn comment(&self) -> Option<CommentView> {
        let s = self.lock();
        let d = s.active()?;
        let c = d.wb.active()?.comments.get(&d.selection.active)?;
        Some(CommentView {
            author: c.author.clone(),
            text: c.text.clone(),
            replies: c.replies.iter().map(|(a, t)| CommentReply { author: a.clone(), text: t.clone() }).collect(),
            threaded: c.threaded,
            resolved: c.resolved,
        })
    }

    /// The comments and notes on the active sheet, in reading order (row by row).
    pub fn comments(&self) -> Vec<CommentItem> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(sh) = wb.sheet(si) else { return vec![] };
        let mut out: Vec<CommentItem> = sh
            .comments
            .iter()
            .take(10_000)
            .map(|(c, m)| CommentItem {
                row: c.row,
                col: c.col,
                cell: c.a1(),
                author: m.author.clone(),
                text: m.text.chars().take(2_000).collect(),
                replies: u32::try_from(m.replies.len()).unwrap_or(u32::MAX),
                threaded: m.threaded,
                resolved: m.resolved,
            })
            .collect();
        out.sort_by_key(|i| (i.row, i.col));
        out
    }

    /// The conditional formatting rules on the active sheet, in the order `home.manageRules`
    /// counts them.
    pub fn cond_formats(&self) -> Vec<RuleItem> {
        let Some((wb, si, _)) = self.snapshot() else { return vec![] };
        let Some(sh) = wb.sheet(si) else { return vec![] };
        sh.cond_formats.iter().take(1_000).map(|cf| rule_item(&wb, cf)).collect()
    }

    /// The workbook holds a note (an unthreaded comment) on any sheet: Convert All Notes has
    /// something to convert.
    pub fn has_notes(&self) -> bool {
        let Some((wb, _, _)) = self.snapshot() else { return false };
        wb.sheets.iter().any(|sh| sh.comments.values().any(|c| !c.threaded))
    }

    /// Where the link in the active cell goes, if it has one.
    pub fn link(&self) -> Option<String> {
        let s = self.lock();
        let d = s.active()?;
        Some(d.wb.active()?.hyperlinks.get(&d.selection.active)?.target.clone())
    }

    /// The name comments are signed with.
    pub fn set_author(&self, name: String) {
        let name = name.trim();
        if !name.is_empty() {
            self.lock().prefs.user_name = name.chars().take(64).collect();
        }
    }

    /// The workbook theme's fonts: headings, then body.
    pub fn theme_fonts(&self) -> Vec<String> {
        let theme = self.snapshot().map(|(wb, _, _)| wb.theme.clone()).unwrap_or_default();
        vec![theme.major_font, theme.minor_font]
    }

    /// The colours the colour menus offer, from the workbook's theme.
    pub fn color_choices(&self) -> ColorChoices {
        let theme = self.snapshot().map(|(wb, _, _)| wb.theme.clone()).unwrap_or_default();
        color_choices(&theme)
    }

    /// Show sheet `index` (0-based, as in [`WorkbookInfo::sheets`]).
    pub fn activate_sheet(&self, index: u32) -> Result<WorkbookInfo, MobileError> {
        let mut s = self.lock();
        Self::run(&mut s, "sheet.activate", json!({ "sheet": index }))?;
        Ok(info(&s))
    }
}

fn cell_format(st: &Style, merged: bool) -> CellFormat {
    let code = st.num_fmt.as_str().to_string();
    CellFormat {
        font: st.font.name.clone(),
        size: st.font.size,
        bold: st.font.bold,
        italic: st.font.italic,
        underline: st.font.underline != Underline::None,
        strike: st.font.strike,
        across: across(st.align.h),
        down: down(st.align.v),
        wrap: st.align.wrap,
        merged,
        reading_order: st.align.reading_order,
        rotation: st.align.rotation,
        indent: st.align.indent,
        number_kind: number_kind(&code).to_string(),
        number_code: code,
        row_height: 0.0,
        col_width: 0.0,
    }
}

/// Whether a cell's look is cell style `st`'s: its fill, font colour and emphasis, borders, and its
/// size where the style sets one.
fn looks_like(cell: &Style, st: &Style) -> bool {
    let default_size = Style::default().font.size;
    cell.fill == st.fill
        && cell.font.color == st.font.color
        && cell.font.bold == st.font.bold
        && cell.font.italic == st.font.italic
        && cell.borders == st.borders
        && (st.font.size == default_size || cell.font.size == st.font.size)
}

/// A border style's name as the border commands take it (`thin`, `mediumDashDotDot`…).
fn border_name(s: BorderStyle) -> String {
    let n = format!("{s:?}");
    n.chars().next().map(|f| f.to_ascii_lowercase().to_string() + &n[f.len_utf8()..]).unwrap_or_default()
}

/// What kind of number format a code is, as the Number Format list names them.
fn number_kind(code: &str) -> &'static str {
    let lower = code.to_ascii_lowercase();
    // quoted text, escaped characters and colours in brackets don't count
    let mut bare = String::new();
    let (mut quoted, mut bracket) = (false, false);
    let mut chars = lower.chars();
    while let Some(ch) = chars.next() {
        match ch {
            '"' => quoted = !quoted,
            '\\' if !quoted => {
                chars.next();
            }
            '[' if !quoted => bracket = true,
            ']' if !quoted => bracket = false,
            c if !quoted && !bracket => bare.push(c),
            _ => {}
        }
    }
    let first = bare.split(';').next().unwrap_or("").to_string();
    if lower == "general" {
        "General"
    } else if lower == "@" {
        "Text"
    } else if first.contains("e+") || first.contains("e-") {
        "Scientific"
    } else if first.contains('%') {
        "Percentage"
    } else if first.contains('?') && first.contains('/') {
        "Fraction"
    } else if first.contains('h') || first.contains('s') || first.contains("am/pm") {
        if first.contains('d') || first.contains('y') { "Date" } else { "Time" }
    } else if first.contains('d') || first.contains('y') || (first.contains('m') && !first.contains('0')) {
        "Date"
    } else if code.starts_with("_(") || code.starts_with("_-") || code.contains("* ") {
        "Accounting"
    } else if ["$", "€", "£", "¥", "[$"].iter().any(|c| code.contains(c)) {
        "Currency"
    } else if first.contains('0') || first.contains('#') {
        "Number"
    } else {
        "Custom"
    }
}

fn across(h: HAlign) -> Across {
    match h {
        HAlign::General => Across::General,
        HAlign::Left => Across::Left,
        HAlign::Center => Across::Center,
        HAlign::Right => Across::Right,
        HAlign::Fill => Across::Fill,
        HAlign::Justify => Across::Justify,
        HAlign::CenterAcross => Across::CenterAcross,
        HAlign::Distributed => Across::Distributed,
    }
}

fn down(v: VAlign) -> Down {
    match v {
        VAlign::Top => Down::Top,
        VAlign::Center => Down::Center,
        VAlign::Bottom => Down::Bottom,
        VAlign::Justify => Down::Justify,
        VAlign::Distributed => Down::Distributed,
    }
}

/// The colour grid. Each theme colour's column holds the colour and five tints of it (positive
/// lighter, negative darker): white gets darker shades from 5 to 50%, black lighter ones from 50
/// to 5%, other dark colours lighter ones, other light colours darker ones, and the rest three
/// lighter and two darker.
fn color_choices(theme: &gridcraft_engine::model::Theme) -> ColorChoices {
    let tints = |i: usize| -> [f64; 5] {
        let rgb = theme.colors.get(i).copied().unwrap_or(0);
        let (r, g, b) = (f64::from((rgb >> 16) & 0xFF), f64::from((rgb >> 8) & 0xFF), f64::from(rgb & 0xFF));
        let l = (r.max(g).max(b) + r.min(g).min(b)) / 2.0 / 255.0;
        // as the phone app's grid: by how light the colour is, white and black included (black
        // 90% to 10% lighter, white 10% to 90% darker)
        match i {
            _ if l < 0.2 => [0.9, 0.75, 0.5, 0.25, 0.1],
            _ if l > 0.8 => [-0.1, -0.25, -0.5, -0.75, -0.9],
            _ => [0.8, 0.6, 0.4, -0.25, -0.5],
        }
    };
    let swatch = |i: usize, tint: f64| {
        let c = Color::Theme(i as u8, (tint * 1000.0).round() as i16);
        let color = if tint == 0.0 { json!({ "theme": i }) } else { json!({ "theme": i, "tint": tint }) };
        Swatch { color: color.to_string(), argb: argb(c.resolve(theme).unwrap_or([0, 0, 0])) }
    };
    let mut rows = vec![(0..10).map(|i| swatch(i, 0.0)).collect::<Vec<_>>()];
    for k in 0..5 {
        rows.push((0..10).map(|i| swatch(i, tints(i)[k])).collect());
    }
    let standard = [0xC00000u32, 0xFF0000, 0xFFC000, 0xFFFF00, 0x92D050, 0x00B050, 0x00B0F0, 0x0070C0, 0x002060, 0x7030A0]
        .iter()
        .map(|&c| Swatch { color: json!(format!("#{c:06X}")).to_string(), argb: argb([(c >> 16) as u8, (c >> 8) as u8, c as u8]) })
        .collect();
    ColorChoices { theme: rows, standard }
}

/// A straight RGBA colour as an ARGB colour int.
fn rgba(c: gridcraft_chart::Rgba) -> i32 {
    ((u32::from(c[3]) << 24) | (u32::from(c[0]) << 16) | (u32::from(c[1]) << 8) | u32::from(c[2])) as i32
}

fn flat(pts: &[[f32; 2]]) -> Vec<f32> {
    pts.iter().flat_map(|p| [p[0], p[1]]).collect()
}

fn prim(p: gridcraft_chart::Prim) -> ChartPrim {
    use gridcraft_chart::{HAlign as H, Prim as P, VAlign as V};
    let stroke = |s: Option<(gridcraft_chart::Rgba, f32)>| (s.map(|(c, _)| rgba(c)), s.map_or(0.0, |(_, w)| w));
    match p {
        P::Rect { x, y, w, h, fill, stroke: st, radius } => {
            let (stroke, stroke_width) = stroke(st);
            ChartPrim::Rect { x, y, w, h, fill: fill.map(rgba), stroke, stroke_width, radius }
        }
        P::Line { pts, color, width, dash } => ChartPrim::Line { points: flat(&pts), color: rgba(color), width, dash },
        P::Polygon { pts, fill, stroke: st } => {
            let (stroke, stroke_width) = stroke(st);
            ChartPrim::Polygon { points: flat(&pts), fill: rgba(fill), stroke, stroke_width }
        }
        P::Wedge { cx, cy, r_outer, r_inner, a0, a1, fill, stroke: st } => {
            let (stroke, stroke_width) = stroke(st);
            ChartPrim::Wedge { cx, cy, r_outer, r_inner, a0, a1, fill: rgba(fill), stroke, stroke_width }
        }
        P::Circle { cx, cy, r, fill, stroke: st } => {
            let (stroke, stroke_width) = stroke(st);
            ChartPrim::Circle { cx, cy, r, fill: fill.map(rgba), stroke, stroke_width }
        }
        P::Text { x, y, text, size, color, bold, align, valign, rotation } => ChartPrim::Text {
            x,
            y,
            text,
            size,
            color: rgba(color),
            bold,
            across: match align {
                H::Left => TextAnchor::Start,
                H::Center => TextAnchor::Middle,
                H::Right => TextAnchor::End,
            },
            down: match valign {
                V::Top => TextAnchor::Start,
                V::Middle => TextAnchor::Middle,
                V::Bottom => TextAnchor::End,
            },
            rotation,
        },
    }
}

fn empty_view() -> SheetView {
    SheetView {
        default_col_width: gridcraft_engine::model::DEFAULT_COL_WIDTH,
        default_row_height: gridcraft_engine::model::DEFAULT_ROW_HEIGHT,
        frozen_rows: 0,
        frozen_cols: 0,
        used_rows: 0,
        used_cols: 0,
        max_rows: MAX_ROWS,
        max_cols: MAX_COLS,
        gridlines: true,
        headings: true,
        right_to_left: false,
        zoom: 100,
        filtered_rows: None,
        autofilter: false,
        show_formulas: false,
        row_levels: 0,
        col_levels: 0,
        row_groups: vec![],
        col_groups: vec![],
    }
}

fn outline_groups(lines: &std::collections::BTreeMap<u32, gridcraft_engine::model::LineInfo>) -> Vec<OutlineGroupView> {
    gridcraft_engine::outline::groups(lines)
        .into_iter()
        .take(10_000)
        .map(|g| OutlineGroupView { level: g.level, start: g.start, end: g.end, collapsed: g.collapsed })
        .collect()
}

/// Header cell `c` heads a column with a filter on it (the sheet's AutoFilter or a table's).
fn column_filtered(sh: &Sheet, c: CellRef) -> bool {
    let on = |range: RangeRef, criteria: &[(u32, gridcraft_engine::model::FilterCriterion)]| {
        range.start.row == c.row && range.contains(c) && criteria.iter().any(|(o, _)| *o == c.col - range.start.col)
    };
    sh.autofilter.as_ref().is_some_and(|af| on(af.range, &af.criteria)) || sh.tables.iter().any(|t| t.header_row && on(t.range, &t.filter))
}

/// The data rows under a filter that has criteria (the sheet's AutoFilter, else a table's).
fn filtered_rows(sh: &Sheet) -> Option<RowSpan> {
    let span = |r: RangeRef| (r.end.row > r.start.row).then(|| RowSpan { first: r.start.row + 1, last: r.end.row });
    if let Some(af) = sh.autofilter.as_ref().filter(|af| !af.criteria.is_empty()) {
        return span(af.range);
    }
    sh.tables.iter().find(|t| !t.filter.is_empty() && t.header_row).and_then(|t| span(t.range))
}

fn info(s: &Session) -> WorkbookInfo {
    let Some(d) = s.active() else {
        return WorkbookInfo {
            document_id: 0,
            revision: 0,
            title: String::new(),
            path: None,
            dirty: false,
            can_undo: false,
            can_redo: false,
            undo_label: None,
            redo_label: None,
            sheets: vec![],
            active_sheet: 0,
            structure_locked: false,
            structure_password: false,
            calc_mode: "automatic".into(),
        };
    };
    let theme = &d.wb.theme;
    WorkbookInfo {
        document_id: d.uid,
        revision: d.revision,
        title: d.display_title(),
        path: d.path.clone(),
        dirty: d.is_dirty(),
        can_undo: !d.undo.is_empty(),
        can_redo: !d.redo.is_empty(),
        undo_label: d.undo.last().map(|h| h.label.clone()),
        redo_label: d.redo.last().map(|h| h.label.clone()),
        sheets: d
            .wb
            .sheets
            .iter()
            .map(|sh| SheetTab {
                name: sh.name.clone(),
                hidden: sh.visibility != Visibility::Visible,
                protected: sh.is_protected(),
                password: sh.protection.as_ref().is_some_and(|p| p.password.is_some() || p.legacy_password_hash.is_some()),
                tab_color: sh.tab_color.and_then(|c| c.resolve(theme)).map(argb),
            })
            .collect(),
        active_sheet: u32::try_from(d.wb.active_sheet).unwrap_or(0),
        structure_locked: d.wb.protected_structure,
        structure_password: d.wb.structure_password.is_some(),
        calc_mode: match d.wb.calc.mode {
            gridcraft_engine::model::CalcMode::Automatic => "automatic",
            gridcraft_engine::model::CalcMode::AutomaticExceptTables => "automaticExceptTables",
            gridcraft_engine::model::CalcMode::Manual => "manual",
        }
        .into(),
    }
}

fn selection_view(s: &Session) -> SelectionView {
    let Some(d) = s.active() else {
        return SelectionView { active_row: 0, active_col: 0, ranges: vec![], name_box: String::new(), formula: String::new(), editable: false };
    };
    let sel: &Selection = &d.selection;
    let wb = &d.wb;
    let c = sel.active;
    let (formula, editable) = match wb.active() {
        Some(sh) => {
            let locked = sh.is_protected() && wb.styles.get(sh.style_id(c)).protection.locked;
            let hidden = gridcraft_engine::display::formula_hidden(wb, sh, c);
            (if hidden { String::new() } else { gridcraft_engine::display::edit_text(wb, sh, c) }, !locked)
        }
        None => (String::new(), false),
    };
    // a defined name that is exactly the selection names it in the name box
    let current = sel.current();
    let sheet_name = wb.active().map(|sh| sh.name.clone()).unwrap_or_default();
    let named = (sel.ranges.len() == 1)
        .then(|| {
            wb.names.iter().find(|n| {
                let target = n.formula.trim_start_matches('=');
                let local = target.rsplit_once('!').map_or(target, |(sheet, r)| if sheet.trim_matches('\'') == sheet_name { r } else { "" });
                // compared as ranges: `$B:$B` and `$B$1:$B$1048576` are both column B
                !local.is_empty() && RangeRef::parse(local) == Some(current)
            })
        })
        .flatten()
        .map(|n| n.name.clone());
    SelectionView {
        active_row: c.row,
        active_col: c.col,
        ranges: sel.ranges.iter().map(|r| CellRange::from(*r)).collect(),
        name_box: named.unwrap_or_else(|| c.a1()),
        formula,
        editable,
    }
}

/// A conditional formatting rule in words, with its colours.
fn rule_item(wb: &Workbook, cf: &gridcraft_engine::model::CondFormat) -> RuleItem {
    use gridcraft_engine::model::{CfOperator as Op, CfRule as R};
    let quoted = |what: &str, t: &str| format!("Cell Value {what} \"{t}\"");
    let rule = match &cf.rule {
        R::CellIs { op, a, b, .. } => {
            let b = b.as_deref().unwrap_or("");
            match op {
                Op::Between => format!("Cell Value between {a} and {b}"),
                Op::NotBetween => format!("Cell Value not between {a} and {b}"),
                Op::Equal => format!("Cell Value = {a}"),
                Op::NotEqual => format!("Cell Value <> {a}"),
                Op::Greater => format!("Cell Value > {a}"),
                Op::Less => format!("Cell Value < {a}"),
                Op::GreaterOrEqual => format!("Cell Value >= {a}"),
                Op::LessOrEqual => format!("Cell Value <= {a}"),
            }
        }
        R::Expression { formula, .. } => format!("Formula: ={formula}"),
        R::ContainsText { text, .. } => quoted("contains", text),
        R::NotContainsText { text, .. } => quoted("does not contain", text),
        R::BeginsWith { text, .. } => quoted("begins with", text),
        R::EndsWith { text, .. } => quoted("ends with", text),
        R::Blanks { .. } => "Blanks".into(),
        R::NoBlanks { .. } => "No Blanks".into(),
        R::Errors { .. } => "Errors".into(),
        R::NoErrors { .. } => "No Errors".into(),
        R::Duplicate { .. } => "Duplicate Values".into(),
        R::Unique { .. } => "Unique Values".into(),
        R::Top10 { bottom, percent, rank, .. } => format!("{} {rank}{}", if *bottom { "Bottom" } else { "Top" }, if *percent { "%" } else { "" }),
        R::AboveAverage { below, equal, .. } => {
            format!("{}{} Average", if *below { "Below" } else { "Above" }, if *equal { " or Equal to" } else { "" })
        }
        R::TimePeriod { period, .. } => format!(
            "Date Occurring: {}",
            match period.as_str() {
                "yesterday" => "Yesterday",
                "today" => "Today",
                "tomorrow" => "Tomorrow",
                "last7Days" => "In the last 7 days",
                "lastWeek" => "Last week",
                "thisWeek" => "This week",
                "nextWeek" => "Next week",
                "lastMonth" => "Last month",
                "thisMonth" => "This month",
                "nextMonth" => "Next month",
                other => other,
            }
        ),
        R::ColorScale { .. } => "Graded Color Scale".into(),
        R::DataBar { .. } => "Data Bar".into(),
        R::IconSet { .. } => "Icon Set".into(),
    };
    let style = match &cf.rule {
        R::CellIs { style, .. }
        | R::Expression { style, .. }
        | R::ContainsText { style, .. }
        | R::NotContainsText { style, .. }
        | R::BeginsWith { style, .. }
        | R::EndsWith { style, .. }
        | R::Blanks { style }
        | R::NoBlanks { style }
        | R::Errors { style }
        | R::NoErrors { style }
        | R::Duplicate { style }
        | R::Unique { style }
        | R::Top10 { style, .. }
        | R::AboveAverage { style, .. }
        | R::TimePeriod { style, .. } => Some(style),
        R::ColorScale { .. } | R::DataBar { .. } | R::IconSet { .. } => None,
    };
    let colors = match &cf.rule {
        R::ColorScale { stops } => stops.iter().filter_map(|(_, c)| c.resolve(&wb.theme).map(argb)).collect(),
        R::DataBar { color, .. } => color.resolve(&wb.theme).map(argb).into_iter().collect(),
        _ => vec![],
    };
    let icons = match &cf.rule {
        R::IconSet { set, .. } => set.clone(),
        _ => String::new(),
    };
    RuleItem {
        rule,
        applies_to: cf.ranges.iter().map(|r| r.a1()).collect::<Vec<_>>().join(","),
        fill: style.filter(|s| s.fill.pattern != PatternType::None).and_then(|s| s.fill.fg.resolve(&wb.theme).map(argb)),
        text: style.filter(|s| s.font.color != Color::Auto).and_then(|s| s.font.color.resolve(&wb.theme).map(argb)),
        colors,
        icons,
    }
}

/// An RGB colour as an opaque ARGB colour int.
fn argb(c: [u8; 3]) -> i32 {
    (0xFF00_0000u32 | (u32::from(c[0]) << 16) | (u32::from(c[1]) << 8) | u32::from(c[2])) as i32
}

/// An opaque ARGB colour made `alpha` (0 to 1) solid.
fn with_alpha(c: i32, alpha: f32) -> i32 {
    let a = if alpha.is_finite() { (alpha.clamp(0.0, 1.0) * 255.0).round() as u32 } else { 255 };
    ((c as u32 & 0x00FF_FFFF) | (a << 24)) as i32
}

fn color_or(c: Color, wb: &Workbook, default: [u8; 3]) -> i32 {
    argb(c.resolve(&wb.theme).unwrap_or(default))
}

fn numfmt_color(c: gridcraft_engine::numfmt::FormatColor) -> i32 {
    use gridcraft_engine::numfmt::FormatColor as F;
    argb(match c {
        F::Black | F::Indexed(_) => [0, 0, 0],
        F::Blue => [0, 0, 255],
        F::Cyan => [0, 255, 255],
        F::Green => [0, 128, 0],
        F::Magenta => [255, 0, 255],
        F::Red => [255, 0, 0],
        F::White => [255, 255, 255],
        F::Yellow => [255, 255, 0],
    })
}

fn stroke(s: BorderStyle) -> Option<Stroke> {
    Some(match s {
        BorderStyle::None => return None,
        BorderStyle::Thin => Stroke::Thin,
        BorderStyle::Medium => Stroke::Medium,
        BorderStyle::Thick => Stroke::Thick,
        BorderStyle::Dashed => Stroke::Dashed,
        BorderStyle::Dotted => Stroke::Dotted,
        BorderStyle::Double => Stroke::Double,
        BorderStyle::Hair => Stroke::Hair,
        BorderStyle::MediumDashed => Stroke::MediumDashed,
        BorderStyle::DashDot => Stroke::DashDot,
        BorderStyle::MediumDashDot => Stroke::MediumDashDot,
        BorderStyle::DashDotDot => Stroke::DashDotDot,
        BorderStyle::MediumDashDotDot => Stroke::MediumDashDotDot,
        BorderStyle::SlantDashDot => Stroke::SlantDashDot,
    })
}

fn edge(b: BorderLine, wb: &Workbook) -> Option<Edge> {
    Some(Edge { stroke: stroke(b.style)?, color: color_or(b.color, wb, [0, 0, 0]) })
}

/// A cell's style with its table's style and conditional formats applied, and its fill colour.
fn look(wb: &Workbook, si: usize, sh: &Sheet, c: CellRef, cf: &mut CfCache) -> (Style, Option<i32>, Option<CfLook>) {
    let mut style = wb.styles.get(sh.style_id(c)).clone();
    if let Some(t) = sh.table_at(c) {
        style = gridcraft_engine::tables::table_cell_style(wb, si, t, c);
    }
    let cfl = if sh.cond_formats.is_empty() { None } else { cf.look(wb, si, c) };
    if let Some(st) = cfl.as_ref().and_then(|l| l.style.as_ref()) {
        if st.fill.pattern != PatternType::None {
            style.fill = st.fill;
        }
        if st.font.color != Color::Auto {
            style.font.color = st.font.color;
        }
        style.font.bold |= st.font.bold;
        style.font.italic |= st.font.italic;
        if st.font.underline != Underline::None {
            style.font.underline = st.font.underline;
        }
        style.font.strike |= st.font.strike;
        // in a differential style General means "not set"
        if st.num_fmt.as_str() != "General" {
            style.num_fmt = st.num_fmt.clone();
        }
        for (dst, src) in [
            (&mut style.borders.left, st.borders.left),
            (&mut style.borders.right, st.borders.right),
            (&mut style.borders.top, st.borders.top),
            (&mut style.borders.bottom, st.borders.bottom),
        ] {
            if !src.is_none() {
                *dst = src;
            }
        }
    }
    let mut fill = match style.fill.pattern {
        PatternType::None => None,
        PatternType::Solid => style.fill.fg.resolve(&wb.theme).map(argb),
        _ => {
            // a pattern is drawn as its two colours blended, a quarter of the foreground
            let fg = style.fill.fg.resolve(&wb.theme).unwrap_or([0, 0, 0]);
            let bg = style.fill.bg.resolve(&wb.theme).unwrap_or([255, 255, 255]);
            let mix = |i: usize| ((u16::from(fg[i]) + u16::from(bg[i]) * 3) / 4) as u8;
            Some(argb([mix(0), mix(1), mix(2)]))
        }
    };
    if let Some(rgb) = cfl.as_ref().and_then(|l| l.scale_fill) {
        fill = Some(argb(rgb));
    }
    (style, fill, cfl)
}

/// What a cell shows: its text, the number format's colour, whether it counts as a number, and
/// the character a format repeats to fill the cell.
fn shown(wb: &Workbook, sh: &Sheet, c: CellRef, v: &Value, st: &Style, width: f32, digit: f32) -> (String, Option<i32>, bool, Option<char>) {
    if sh.show_formulas
        && let Some(f) = sh.cell(c).and_then(|x| x.formula.as_ref())
    {
        return (format!("={}", f.text), None, false, None);
    }
    if !sh.show_zeros && v.as_f64() == Some(0.0) {
        return (String::new(), None, false, None);
    }
    let code = st.num_fmt.as_str();
    // a checkbox cell draws its box; the app has no checkbox cells yet, so it shows nothing
    if code == "checkbox" && matches!(v, Value::Bool(_) | Value::Empty) {
        return (String::new(), None, false, None);
    }
    if code == "General"
        && let Value::Number(n) = v
    {
        let max_chars = ((width - 4.0) / digit).floor().max(1.0) as usize;
        return match gridcraft_engine::numfmt::format_general_fit(*n, max_chars.min(11)) {
            Some(t) => (t, None, true, None),
            None => ("#".repeat(max_chars.clamp(1, 255)), None, true, None),
        };
    }
    let f = gridcraft_engine::display::format(v, code, wb);
    (f.text, f.color.map(numfmt_color), f.numeric, f.fill.map(|(ch, _)| ch))
}

/// The lines `first..=last` of an axis, hidden ones left out: (index, start, size).
fn lines(first: u32, last: u32, max: u32, start_of: impl Fn(u32) -> f64, size_of: impl Fn(u32) -> f32) -> Vec<Line> {
    let last = last.min(max.saturating_sub(1));
    let first = first.min(last);
    let mut out = Vec::new();
    let mut at = start_of(first);
    for i in first..=last {
        let size = size_of(i);
        if size > 0.0 {
            out.push(Line { index: i, start: at, size });
        }
        at += f64::from(size);
    }
    out
}

fn build_viewport(wb: &Workbook, si: usize, revision: u64, area: (u32, u32, u32, u32), digit: f32) -> Viewport {
    let (first_row, first_col, last_row, last_col) = area;
    let sheet = u32::try_from(si).unwrap_or(0);
    let Some(sh) = wb.sheet(si) else {
        return Viewport { sheet, revision, rows: vec![], cols: vec![], cells: vec![], merges: vec![], sparklines: vec![] };
    };
    let mut rows = lines(first_row, last_row, MAX_ROWS, |r| sh.row_top(r), |r| sh.row_height(r));
    let mut cols = lines(first_col, last_col, MAX_COLS, |c| sh.col_left(c), |c| sh.col_width(c));
    // a hostile request is cut down to what a screen could show
    while (rows.len() as u64) * (cols.len() as u64) > MAX_VIEW_CELLS {
        if rows.len() >= cols.len() {
            rows.truncate(rows.len() / 2);
        } else {
            cols.truncate(cols.len() / 2);
        }
    }
    let (Some(r0), Some(r1), Some(c0), Some(c1)) = (rows.first(), rows.last(), cols.first(), cols.last()) else {
        return Viewport { sheet, revision, rows, cols, cells: vec![], merges: vec![], sparklines: vec![] };
    };
    let area = RangeRef::new(CellRef::new(r0.index, c0.index), CellRef::new(r1.index, c1.index));
    let merges: Vec<CellRange> = sh.merges.iter().filter(|m| m.intersection(&area).is_some()).map(|m| CellRange::from(*m)).collect();
    let mut cf = CfCache::default();
    let mut cells = Vec::new();
    for r in &rows {
        for col in &cols {
            let c = CellRef::new(r.index, col.index);
            // a merged block is drawn by its first cell, across the whole block
            let merge = sh.merge_at(c);
            if merge.is_some_and(|m| m.start != c) {
                continue;
            }
            let width = match merge {
                Some(m) => (sh.col_left(m.end.col.saturating_add(1)) - sh.col_left(m.start.col)) as f32,
                None => col.size,
            };
            let (style, fill, cfl) = look(wb, si, sh, c, &mut cf);
            let value = sh.value(c);
            let hide = cfl.as_ref().is_some_and(|l| l.hide_value);
            // a picture placed in the cell shows instead of its value
            let picture = sh.cell_pictures.contains_key(&c);
            let (text, fmt_color, numeric, repeat) =
                if value.is_empty() || hide || picture { (String::new(), None, false, None) } else { shown(wb, sh, c, &value, &style, width, digit) };
            let b = &style.borders;
            let (left, top, right, bottom) = (edge(b.left, wb), edge(b.top, wb), edge(b.right, wb), edge(b.bottom, wb));
            let bar = cfl.as_ref().and_then(|l| l.bar).map(|(f, rgb, gradient)| DataBar { fraction: f.clamp(0.0, 1.0), color: argb(rgb), gradient });
            let icon = cfl.as_ref().and_then(|l| l.icon.clone()).map(|(set, i)| CellIcon { set, index: u32::try_from(i).unwrap_or(0) });
            let comment = sh.comments.contains_key(&c);
            let threaded_comment = sh.comments.get(&c).is_some_and(|cm| cm.threaded);
            let link = sh.hyperlinks.contains_key(&c);
            let filter_button = sh.has_filter_button(c);
            let filtered = filter_button && column_filtered(sh, c);
            let checkbox = match value {
                Value::Bool(b) if style.num_fmt.as_str() == "checkbox" => Some(b),
                Value::Empty if style.num_fmt.as_str() == "checkbox" => Some(false),
                _ => None,
            };
            let shows = checkbox.is_some()
                || picture
                || !text.is_empty()
                || fill.is_some()
                || [left, top, right, bottom].iter().any(Option::is_some)
                || bar.is_some()
                || icon.is_some()
                || comment
                || filter_button;
            if !shows {
                continue;
            }
            let font = &style.font;
            let a = &style.align;
            let rtl = a.h == HAlign::General && !numeric && gridcraft_engine::display::reads_right_to_left(a.reading_order, &text);
            cells.push(CellView {
                row: c.row,
                col: c.col,
                text,
                color: fmt_color.unwrap_or_else(|| color_or(font.color, wb, [0, 0, 0])),
                auto_color: fmt_color.is_none() && font.color == Color::Auto,
                fill,
                font: font.name.clone(),
                size: font.size,
                bold: font.bold,
                italic: font.italic,
                underline: match font.underline {
                    Underline::None => 0,
                    Underline::Double | Underline::DoubleAccounting => 2,
                    _ => 1,
                },
                strike: font.strike,
                across: if rtl { Across::Right } else { across(a.h) },
                down: down(a.v),
                numeric,
                centred: matches!(value, Value::Bool(_) | Value::Error(_)),
                wrap: a.wrap,
                shrink: a.shrink,
                indent: a.indent,
                rotation: a.rotation,
                repeat: repeat.map(String::from),
                left,
                top,
                right,
                bottom,
                bar,
                icon,
                comment,
                threaded_comment,
                link,
                filter_button,
                filtered,
                checkbox,
                picture,
            });
        }
    }
    // sparklines, drawn inside their cells with a small margin
    let mut sparklines = Vec::new();
    for sp in sh.sparklines.iter().filter(|sp| area.contains(sp.cell)).take(2_000) {
        let (Some(r), Some(c)) = (rows.iter().find(|l| l.index == sp.cell.row), cols.iter().find(|l| l.index == sp.cell.col)) else { continue };
        let (w, h) = ((c.size - 6.0).max(1.0), (r.size - 6.0).max(1.0));
        let vals: Vec<Option<f64>> = match gridcraft_engine::calc::evaluate(wb, si, sp.cell, &sp.source) {
            Value::Array(a) => a.data.iter().take(10_000).map(Value::as_f64).collect(),
            v => vec![v.as_f64()],
        };
        let rgb = sp.color.resolve(&wb.theme).unwrap_or([0x2B, 0x7C, 0xD3]);
        let prims = gridcraft_chart::render_sparkline(sp.kind, &vals, [rgb[0], rgb[1], rgb[2], 255], sp.markers, w, h);
        // moved in by the margin, so the drawing is in the cell's own space
        let prims = prims.into_iter().map(|p| offset(prim(p), 3.0, 3.0)).collect();
        sparklines.push(SparklineView { row: sp.cell.row, col: sp.cell.col, prims });
    }
    Viewport { sheet, revision, rows, cols, cells, merges, sparklines }
}

/// A chart step moved by (`dx`, `dy`).
fn offset(p: ChartPrim, dx: f32, dy: f32) -> ChartPrim {
    let shift = |pts: Vec<f32>| pts.chunks(2).flat_map(|c| [c.first().copied().unwrap_or(0.0) + dx, c.get(1).copied().unwrap_or(0.0) + dy]).collect();
    match p {
        ChartPrim::Rect { x, y, w, h, fill, stroke, stroke_width, radius } => {
            ChartPrim::Rect { x: x + dx, y: y + dy, w, h, fill, stroke, stroke_width, radius }
        }
        ChartPrim::Line { points, color, width, dash } => ChartPrim::Line { points: shift(points), color, width, dash },
        ChartPrim::Polygon { points, fill, stroke, stroke_width } => ChartPrim::Polygon { points: shift(points), fill, stroke, stroke_width },
        ChartPrim::Wedge { cx, cy, r_outer, r_inner, a0, a1, fill, stroke, stroke_width } => {
            ChartPrim::Wedge { cx: cx + dx, cy: cy + dy, r_outer, r_inner, a0, a1, fill, stroke, stroke_width }
        }
        ChartPrim::Circle { cx, cy, r, fill, stroke, stroke_width } => ChartPrim::Circle { cx: cx + dx, cy: cy + dy, r, fill, stroke, stroke_width },
        ChartPrim::Text { x, y, text, size, color, bold, across, down, rotation } => {
            ChartPrim::Text { x: x + dx, y: y + dy, text, size, color, bold, across, down, rotation }
        }
    }
}
